interface I18nValue { language: Language; setLanguage: (language: Language) => void; t: (text: string) => string }
const I18nContext = createContext<I18nValue | null>(null)

export function translate(text: string, language: Language) {
  return language === 'fa' ? (fa[text] ?? faExtra[text] ?? faMore[text] ?? text) : text
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    try { return localStorage.getItem('alireza-portfolio-language') === 'fa' ? 'fa' : 'en' } catch { return 'en' }
  })
  const setLanguage = useCallback((next: Language) => {
    setLanguageState(next)
    try { localStorage.setItem('alireza-portfolio-language', next) } catch { /* storage may be unavailable */ }
  }, [])
  const t = useCallback((text: string) => translate(text, language), [language])

  useEffect(() => {
    document.documentElement.lang = language
    document.documentElement.dir = language === 'fa' ? 'rtl' : 'ltr'
    document.title = language === 'fa' ? 'علیرضا حبیب‌الهی — مهندس ارشد فرانت‌اند و توسعه‌دهنده بک‌اند' : 'Alireza Habibollahi — Senior Front-End Engineer & Mid-Level Back-End Developer'
  }, [language])

  const value = useMemo(() => ({ language, setLanguage, t }), [language, setLanguage, t])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const value = useContext(I18nContext)
  if (!value) throw new Error('useI18n must be used within I18nProvider')
  return value
}
